// The retail-address stub table generated by port/tools/gen_link.py: one entry per function
// symbol that resolves to a retail address.
// port_install_stubs() writes a jump to the native code at each address, after the retail image
// is loaded (the image would overwrite them).
#ifndef PORT_STUBS_H
#define PORT_STUBS_H

#include <stdint.h>

typedef struct
{
    uint32_t addr;        // retail address (the C symbol's value)
    void (*native)(void); // the native code (port_native_<name>)
    const char *name;
    int missing; // 1 = a reporting stub: no native code yet
} PORT_STUB;

extern const PORT_STUB port_stub_table[];
extern const int port_stub_count;

// Installs every entry. Returns the number installed, or -1 on failure.
int port_install_stubs(void);

// The entry for a retail function address, or NULL.
const PORT_STUB *port_stub_find(uint32_t addr);

// Mod hooks (port/mods/): points the jump at a retail function's address
// at `fn` instead of the native code, so every call reaches fn: native calls (they go through
// the retail address), calls through pointers in retail data, and calls from interpreted MIPS
// code (port_stub_target). Returns the native code, for fn to call on, or NULL when the address
// has no entry or is hooked already. port_stub_unhook puts the native jump back.
void *port_stub_hook(uint32_t addr, void *fn);
void port_stub_unhook(uint32_t addr);
// The code a call to the entry reaches: its hook when one is set, else its native function.
void *port_stub_target(const PORT_STUB *st);

#endif
